63	async function waitForActiveJobsWidget(page: Page): Promise<void> {
64	  // The ActiveJobsWidget injects a <style id="gohufont-active-jobs"> tag
65	  // when it mounts. We wait for that as a fingerprint.
66	  try {
67	    await page.waitForFunction(
68	      () => !!document.getElementById('gohufont-active-jobs'),
69	      { timeout: 20_000 },
70	    );
71	  } catch {
72	    console.warn(
73	      'ActiveJobsWidget font-face tag not found — widget may not be rendered. Continuing anyway.',
74	    );
75	  }
76	
77	  // Let animations settle
78	  await page.waitForTimeout(2000);
79	}
