81	function screenshotFilename(label: string): string {
82	  const ts = new Date().toISOString().replace(/[:.]/g, '-');
83	  const slug = label.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
84	  return `${slug}-${ts}.png`;
85	}
