87	async function sendToDiscord(screenshotPaths: string[]): Promise<void> {
88	  if (!DISCORD_QA_WEBHOOK) {
89	    console.log('DISCORD_QA_WEBHOOK not set — skipping Discord delivery.');
90	    return;
91	  }
92	
93	  const form = new FormData();
94	
95	  const ts = new Date().toISOString();
96	  const embed = {
97	    title: 'QA Screenshot Report',
98	    description: `Captured ${screenshotPaths.length} screenshot(s) at ${ts}`,
99	    color: 0x00bfff,
100	    timestamp: ts,
101	    fields: screenshotPaths.map((p, i) => ({
102	      name: `Screenshot ${i + 1}`,
103	      value: path.basename(p),
104	    })),
105	  };
106	
107	  form.append(
108	    'payload_json',
109	    JSON.stringify({
110	      username: 'PearlOS QA Bot',
111	      embeds: [embed],
112	    }),
113	  );
114	
115	  for (let i = 0; i < screenshotPaths.length; i++) {
116	    form.append(`files[${i}]`, fs.createReadStream(screenshotPaths[i]), {
117	      filename: path.basename(screenshotPaths[i]),
118	      contentType: 'image/png',
119	    });
120	  }
121	
122	  const resp = await new Promise<{ statusCode: number | undefined }>((resolve, reject) => {
123	    form.submit(DISCORD_QA_WEBHOOK!, (err, res) => {
124	      if (err) return reject(err);
125	      res.resume();
126	      resolve({ statusCode: res.statusCode });
127	    });
128	  });
129	
130	  if (resp.statusCode && resp.statusCode >= 200 && resp.statusCode < 300) {
131	    console.log('Screenshots delivered to Discord successfully.');
132	  } else {
133	    console.error(`Discord webhook returned status ${resp.statusCode}`);
134	  }
135	}
